"""生成不连接设备或宿主的屏幕交互预览，复用候选内嵌的原小松鼠素材。"""
import argparse
import base64
import json
from pathlib import Path

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
    assets=Path(__file__).resolve().parents[1]/'main/teloa/assets'
    poses={name:'data:image/png;base64,'+base64.b64encode((assets/(name+'.png')).read_bytes()).decode() for name in ('standing','wink','curious','thinking','reading','celebrating')}
    html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Teloa · 小罗同学屏幕预览</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f3f2ef;color:#242723;font:15px/1.6 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1050px;margin:64px auto;padding:32px;display:grid;grid-template-columns:1fr 410px;gap:60px;align-items:center}small{font-size:12px;color:#646860}h1{font-size:32px;line-height:1.4;margin:14px 0}p{color:#646860;max-width:480px}.eyebrow{color:#2f6c51;letter-spacing:2px;font-weight:600}.screen{position:relative;width:360px;height:360px;border-radius:50%;overflow:hidden;background:#fcfcfb;box-shadow:0 0 0 12px #242723,0 20px 64px #24272325;font:20px/1.2 -apple-system,"PingFang SC",sans-serif;margin:20px auto}.screen>*{position:absolute;text-align:center}.icons{top:25px;left:77px;width:206px;display:flex;justify-content:space-between;font-size:17px;color:#646860}.name{top:54px;left:65px;width:230px}.status{top:82px;left:55px;width:250px}.squirrel{top:100px;left:100px;width:160px;height:160px;object-fit:contain;animation:breathe 2.2s ease-in-out infinite}.screen.speaking .squirrel{animation:breathe .35s ease-in-out infinite}.subtitle{top:265px;left:45px;width:270px;height:28px;overflow:hidden;font-size:20px}.screen button{top:300px;height:32px;border:0;border-radius:17px;background:#eaf3ed;color:#2f6c51;font-size:20px;line-height:1.2;padding:4px 0;font-family:inherit;cursor:pointer}.primary{left:166px;width:106px}.secondary{left:88px;width:74px}.approval{top:107px;left:50px;width:260px;height:168px;white-space:pre-wrap;overflow:hidden;display:none;text-align:center}.card .approval{display:block}.card .squirrel,.card .subtitle{display:none}.switches{display:flex;flex-wrap:wrap;gap:8px;margin-top:25px}.switches button{border:1px solid #e3e4de;background:#fcfcfb;border-radius:8px;padding:9px 15px;font:inherit;color:#242723;cursor:pointer}.switches button[aria-pressed=true]{background:#eaf3ed;border-color:#2f6c51;color:#2f6c51}.caption{text-align:center;color:#646860;font-size:12px;margin-top:30px}.note{padding:16px 0;border-top:1px solid #e3e4de;margin-top:30px}.secondary[hidden]{display:none}@keyframes breathe{50%{transform:translateY(-3px)}}@media(prefers-reduced-motion:reduce){.squirrel{animation:none!important}}@media(max-width:800px){main{display:flex;flex-direction:column;margin:15px auto;gap:20px;padding:28px 15px}h1{font-size:28px}}
</style><main><section><div class="eyebrow">TELOA · 小罗同学</div><h1>同一只小松鼠，<br>现在住进屏幕。</h1><p>沿用工作台已经定稿的绿色毛绒形象。轻轻呼吸、眨眼，听你说话，也陪你等任务完成。</p><div class="switches" aria-label="预览状态"><button data-state="idle" aria-pressed="true">待机</button><button data-state="listening">倾听</button><button data-state="thinking">思考</button><button data-state="speaking">说话</button><button data-state="happy">完成</button></div><div class="note"><strong>点屏幕上的「待确认」试一试</strong><p>翻到最后一页后，长按批准本次操作。这个预览仅演示交互，不连接 Teloa，也不会处理真实审批。</p></div><small>360 × 360 软件预览 · 与候选使用同一组素材<br>屏幕显示、触点和动画效果仍待实机验证；尚未刷写设备。</small></section><section><div class="screen" id="screen"><div class="icons"><span>⌁</span><span>▰</span></div><div class="name">小罗同学</div><div class="status"></div><img class="squirrel" alt="Teloa 现有绿色毛绒小松鼠"><div class="subtitle">我在，随时叫我。</div><div class="approval"></div><button class="secondary" hidden>拒绝</button><button class="primary">待确认</button></div><div class="caption" id="hint">呼吸与眨眼 · 原小松鼠素材</div></section></main><script>
const poses=__POSES__,screen=document.querySelector('#screen'),sprite=document.querySelector('img'),primary=document.querySelector('.primary'),secondary=document.querySelector('.secondary'),name=document.querySelector('.name'),status=document.querySelector('.status'),subtitle=document.querySelector('.subtitle'),approval=document.querySelector('.approval'),hint=document.querySelector('#hint');
let state='idle',card=false,page=0,held=0;const pages=['write_file\\n在工作目录创建测试文件','文件：测试记录.txt\\n内容：联调通过。','仅批准本次操作。\\n长按右下方按钮确认。'];
function select(next){held=0;state=next;card=false;screen.className='screen '+next;secondary.hidden=true;name.textContent='小罗同学';status.textContent='';sprite.src=poses[({listening:'curious',thinking:'thinking',happy:'celebrating'})[state]||'standing'];subtitle.textContent=({idle:'我在，随时叫我。',listening:'我在听。',thinking:'正在整理你的问题。',speaking:'我是小罗同学。',happy:'完成了，结果在 Teloa。'})[state];primary.textContent='待确认';document.querySelectorAll('[data-state]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.state===state?'true':'false'));}
function draw(){screen.className='screen card';name.textContent='等待你确认';status.textContent=(page+1)+' / '+pages.length;approval.textContent=pages[page];primary.textContent=page<pages.length-1?'下一页':'长按批准';secondary.hidden=false;hint.textContent='演示申请 · 只决定本次操作';}
function finish(text){select('idle');subtitle.textContent=text;hint.textContent='预览已结束，未提交真实审批';}
primary.addEventListener('pointerdown',()=>held=performance.now());primary.addEventListener('pointerup',()=>{if(!card){card=true;page=0;draw()}else if(page<pages.length-1){page++;draw()}else if(held>0&&performance.now()-held>=1200)finish('已批准本次操作。');else hint.textContent='请长按 1.2 秒批准本次操作。';held=0});primary.addEventListener('pointercancel',()=>held=0);primary.addEventListener('pointerleave',()=>held=0);secondary.addEventListener('click',()=>finish('已拒绝本次操作。'));document.querySelectorAll('[data-state]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.state)));setInterval(()=>{if(!card&&state==='idle'){sprite.src=poses.wink;setTimeout(()=>{if(!card&&state==='idle')sprite.src=poses.standing},200)}},6000);select('idle');
</script></html>'''.replace('__POSES__',json.dumps(poses))
    with args.output.open('x',encoding='utf-8') as output:output.write(html)
if __name__=='__main__':main()
